{
  "version": 1,
  "schemas": {
    "grok-bot": {
      "name": "grok-bot",
      "version": "1",
      "description": "Grok Bot transcript schema for agent-transcripts/*.jsonl exports",
      "events": [
        {
          "name": "grok-user-message",
          "match": {
            "path": "role",
            "equals": "user"
          },
          "action": "user_message",
          "fields": {
            "prompt": {
              "coalesce": [
                "message.content[0].text",
                "message.content[0].content"
              ]
            }
          }
        },
        {
          "name": "grok-assistant-text",
          "match": {
            "path": "role",
            "equals": "assistant"
          },
          "action": "assistant_message",
          "fields": {
            "message": {
              "coalesce": [
                "message.content[0].text",
                "message.content[0].content"
              ]
            }
          }
        },
        {
          "name": "grok-tool-use",
          "match": {
            "path": "message.content[0].type",
            "equals": "tool_use"
          },
          "action": "tool_use",
          "fields": {
            "toolId": {
              "coalesce": [
                "message.content[0].toolUseId",
                "message.content[0].tool_use_id",
                "message.content[0].id"
              ]
            },
            "toolName": "message.content[0].name",
            "toolInput": {
              "coalesce": [
                "message.content[0].input",
                "message.content[0].arguments"
              ]
            }
          }
        },
        {
          "name": "grok-tool-result",
          "match": {
            "path": "role",
            "equals": "tool"
          },
          "action": "tool_result",
          "fields": {
            "toolId": {
              "coalesce": [
                "message.content[0].toolUseId",
                "message.content[0].tool_use_id",
                "message.content[0].toolId",
                "message.content[0].tool_id",
                "message.content[0].id"
              ]
            },
            "toolUseId": {
              "coalesce": [
                "message.content[0].toolUseId",
                "message.content[0].tool_use_id",
                "message.content[0].toolId",
                "message.content[0].tool_id",
                "message.content[0].id"
              ]
            },
            "toolName": "message.content[0].name",
            "toolResponse": {
              "coalesce": [
                "message.content[0].content",
                "message.content[0].output",
                "message.content[0].text"
              ]
            }
          }
        }
      ]
    }
  },
  "watches": [
    {
      "name": "grok-bot",
      "schema": "grok-bot",
      "path": "<SANDBOX>/workspace/agent-data/agent-transcripts/a1/*.jsonl",
      "workspace": "<SANDBOX>/workspace/agent-data/.cmem-projects/cmem_work_alpha-project",
      "project": "cmem_work_alpha-project",
      "startAtEnd": true,
      "agentId": "a1"
    },
    {
      "name": "grok-bot",
      "schema": "grok-bot",
      "path": "<SANDBOX>/workspace/agent-data/agent-transcripts/*/*.jsonl",
      "workspace": "<SANDBOX>/workspace/agent-data/.cmem-projects/cmem_work_root",
      "project": "cmem_work_root",
      "startAtEnd": true
    }
  ],
  "stateFile": "<SANDBOX>/data/transcript-watch-state.json"
}
